spec.expr:
topk(10,
  sum by (as_number, as_name) (
  crowdsec_alerts_grand_total{
  scenario=~"$scenario",
  as_name=~"$as_name",
  country=~"$country"
  }
  )
)

topk(10,
  sum by (country) (
  floor(increase(
  crowdsec_alerts_grand_total{
  scenario=~"$scenario",
  as_name=~"$as_name",
  country=~"$country"
  }
  [$__range]
  ))
  )
)>0

